<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Sorting Visualizer</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    background: #0f0f1a;
    color: #e0e0ff;
    font-family: system-ui, sans-serif;
    display: flex;
    flex-direction: column;
    align-items: center;
    min-height: 100vh;
    padding: 24px;
  }
  h1 { margin-bottom: 20px; font-size: 1.4rem; letter-spacing: 2px; color: #a0a0ff; }
  #bars {
    display: flex;
    align-items: flex-end;
    gap: 2px;
    width: 100%;
    max-width: 800px;
    height: 360px;
    background: #1a1a2e;
    border: 1px solid #2a2a4a;
    border-radius: 8px;
    padding: 8px;
  }
  .bar {
    flex: 1;
    border-radius: 2px 2px 0 0;
    background: #5555ff;
    transition: height 0.05s ease;
  }
  .bar.comparing { background: #ff5555; }
  .bar.sorted-mark { background: #55ff99; }
  .controls {
    margin-top: 20px;
    display: flex;
    gap: 12px;
  }
  button {
    padding: 10px 24px;
    border: none;
    border-radius: 6px;
    font-size: 0.95rem;
    cursor: pointer;
    font-weight: 600;
    transition: opacity 0.15s;
  }
  button:hover { opacity: 0.85; }
  #sort { background: #5555ff; color: #fff; }
  #shuffle { background: #ff9955; color: #fff; }
  #reset { background: #444466; color: #e0e0ff; }
  #status { margin-top: 12px; font-size: 0.85rem; color: #8080cc; min-height: 1.2em; }
</style>
</head>
<body>
<h1>SORTING VISUALIZER</h1>
<div id="bars"></div>
<div class="controls">
  <button id="sort">Sort</button>
  <button id="shuffle">Shuffle</button>
  <button id="reset">Reset</button>
</div>
<div id="status"></div>

<script>
(function() {
  const DEFAULT_SIZE = 40;
  const ANIM_DELAY = 30;

  let arr = [];
  let barEls = [];
  let animHandle = null;

  // Insertion sort state
  let sortState = null;

  function initSortState() {
    sortState = { i: 1, j: null, key: null, phase: 'start' };
  }

  function generateDefault() {
    const a = [];
    for (let i = 1; i <= DEFAULT_SIZE; i++) a.push(i * 2);
    return a;
  }

  function shuffle(a) {
    const b = a.slice();
    for (let i = b.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [b[i], b[j]] = [b[j], b[i]];
    }
    return b;
  }

  function render() {
    const container = document.getElementById('bars');
    container.innerHTML = '';
    barEls = [];
    const maxVal = Math.max(...arr, 1);
    for (let i = 0; i < arr.length; i++) {
      const bar = document.createElement('div');
      bar.className = 'bar';
      bar.style.height = ((arr[i] / maxVal) * 100) + '%';
      container.appendChild(bar);
      barEls.push(bar);
    }
  }

  function highlightBars(indices, cls) {
    barEls.forEach(b => b.classList.remove('comparing', 'sorted-mark'));
    if (indices) {
      indices.forEach(i => { if (barEls[i]) barEls[i].classList.add(cls); });
    }
  }

  function updateBar(i) {
    const maxVal = Math.max(...arr, 1);
    if (barEls[i]) barEls[i].style.height = ((arr[i] / maxVal) * 100) + '%';
  }

  function isSorted() {
    for (let i = 1; i < arr.length; i++) {
      if (arr[i] < arr[i - 1]) return false;
    }
    return true;
  }

  // Insertion sort, one comparison/shift per call
  // Returns true when fully sorted
  function sortStep() {
    if (isSorted()) return true;

    if (!sortState) initSortState();

    const state = sortState;

    if (state.phase === 'start') {
      if (state.i >= arr.length) {
        initSortState();
        return isSorted();
      }
      state.key = arr[state.i];
      state.j = state.i - 1;
      state.phase = 'compare';
    }

    if (state.phase === 'compare') {
      highlightBars([state.j, state.j + 1], 'comparing');
      if (state.j >= 0 && arr[state.j] > state.key) {
        arr[state.j + 1] = arr[state.j];
        updateBar(state.j + 1);
        state.j--;
        // stay in compare phase for next step
      } else {
        state.phase = 'place';
      }
      return false;
    }

    if (state.phase === 'place') {
      arr[state.j + 1] = state.key;
      updateBar(state.j + 1);
      state.i++;
      state.phase = 'start';
      if (isSorted()) {
        highlightBars(arr.map((_, i) => i), 'sorted-mark');
        return true;
      }
      return false;
    }

    return isSorted();
  }

  function stopAnimation() {
    if (animHandle !== null) {
      clearTimeout(animHandle);
      animHandle = null;
    }
  }

  function animateSort() {
    const done = sortStep();
    document.getElementById('status').textContent = done ? 'Sorted!' : 'Sorting...';
    if (!done) {
      animHandle = setTimeout(animateSort, ANIM_DELAY);
    } else {
      animHandle = null;
    }
  }

  // Public API
  window.viz = {
    array() { return arr.slice(); },
    setArray(a) {
      stopAnimation();
      arr = a.slice();
      initSortState();
      render();
      document.getElementById('status').textContent = '';
    },
    sortStep() { return sortStep(); },
    sorted() { return isSorted(); },
  };

  // Button handlers
  document.getElementById('sort').addEventListener('click', () => {
    stopAnimation();
    if (isSorted()) {
      document.getElementById('status').textContent = 'Already sorted.';
      return;
    }
    animateSort();
  });

  document.getElementById('shuffle').addEventListener('click', () => {
    stopAnimation();
    arr = shuffle(arr);
    initSortState();
    render();
    document.getElementById('status').textContent = '';
  });

  document.getElementById('reset').addEventListener('click', () => {
    stopAnimation();
    arr = shuffle(generateDefault());
    initSortState();
    render();
    document.getElementById('status').textContent = '';
  });

  // Init
  arr = shuffle(generateDefault());
  initSortState();
  render();
})();
</script>
</body>
</html>
